  function tournamentGoalLeader(t){const totals=(t.ps||[]).map((p,i)=>({i,n:p.n,g:0}));[...(t.rounds||[]).flat(),t.final].filter(Boolean).filter(m=>m.st==='ft').forEach(m=>{if(totals[m.a])totals[m.a].g+=m.sa||0;if(totals[m.b])totals[m.b].g+=m.sb||0});return totals.sort((a,b)=>b.g-a.g)[0]||{n:'—',g:0}}
