  function renderMatchReplay(t){const f=t.final||{},A=t.ps[f.a]||{},B=t.ps[f.b]||{},ta=finalTeam(t,f,'a'),tb=finalTeam(t,f,'b'),goals=(f.g||[]);let a=0,b=0;const timeline=goals.map((side,i)=>{side==='a'?a++:b++;return `<li><span>${i+1}'</span><b>${esc(side==='a'?A.n:B.n)}</b><em>${a}–${b}</em></li>`}).join('');return `<section class="pr-v57-replay-card"><button class="pr-v57-skip" data-a="v57replaydone">Close ×</button><div class="pr-champion-kicker">● MATCH REPLAY</div><div class="pr-v57-replay-score"><div>${badge(ta,'lg')}<b>${esc(A.n||'Finalist')}</b></div><strong>${f.sa||0} – ${f.sb||0}</strong><div>${badge(tb,'lg')}<b>${esc(B.n||'Finalist')}</b></div></div>${timeline?`<ol class="pr-v57-goal-timeline">${timeline}</ol>`:'<p class="pr-v57-no-goals">No goals recorded.</p>'}<button class="pr-champion-secondary" data-a="v57replaydone">Back to champion summary</button></section>`}
