  function showV57TrophyCelebration(t){if(!t)return;if(t.trophyLifted){if(typeof toast==='function')toast('Trophy already lifted');return}t.trophyLifted=1;if(typeof save==='function')save();showV57Overlay('prV57Celebration',renderTrophyCelebration(t))}
