    let body='';if(tab==='ovw')body=renderOverview(t);else if(tab==='fix')body=renderFixtures(t);else if(tab==='std')body=renderStandings(t,typeof table==='function'?table(t):[]);else if(tab==='fun')body=renderStats(t);else if(tab==='race')body=renderRace(t);else if(tab==='fin')body=renderFinal(t);else body=renderHistory(t);
